def verificar_correos(apps, schema_editor):
    """Aborta con un mensaje claro si hay correos vacíos o duplicados (sin distinguir mayúsculas)."""
    Funcionario = apps.get_model('alertas', 'Funcionario')
    funcionarios = list(Funcionario.objects.values_list('id', 'email'))
    vacios = sorted(pk for pk, email in funcionarios if not (email or '').strip())
    conteo = Counter((email or '').strip().lower() for _, email in funcionarios)
    duplicados = sorted(email for email, n in conteo.items() if email and n > 1)
    problemas = []
    if vacios:
        problemas.append(f"funcionarios con correo vacío (id): {', '.join(map(str, vacios))}")
    if duplicados:
        problemas.append(f"correos duplicados: {', '.join(duplicados)}")
    if problemas:
        raise RuntimeError(
            "No se puede exigir correo único y no vacío en Funcionario: "
            + "; ".join(problemas)
            + ". Corrígelos manualmente y vuelve a migrar."
        )


